function mostrarHeaderFooter() {
   $.ajax({
      async: !0,
      url: "https://www.prisma.cat/ajax/mostrar_header_2.php",
      cache: !0,
      type: "GET",
      success: function(pagina) {
         $("header").html(pagina);
         $('.closebtn').css('display', 'none');
         if (/Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent))
            $('.navbar-nav > li').addClass('mobile');
         else $('.navbar-nav > li').addClass('computer')

			$('.prisma-header').on('focus', '.form-control', function(){
				$(this).next().next().addClass('active');
			});
			$('.prisma-header').on('blur', '.form-control', function(){
				if ($(this).val()=='')
					$(this).next().next().removeClass('active');
			});
      }
   });
   $.ajax({
      async: !0,
      url: "https://www.prisma.cat/ajax/mostrar_footer_2.php",
      cache: !0,
      type: "GET",
      success: function(pagina) {
         $("footer").html(pagina);

			adjustStyle();

			$(window).resize(function() {
				adjustStyle();
			});

			$('.form-footer').on('focus', '.form-control', function(){
				$('.form-footer label').hide();
			});
			$('.form-footer').on('blur', '.form-control', function(){
				if ($('#adreca-electronica').val()=='')
					$('.form-footer label').show();
			});

			$('.form-footer').on('click', '#news', function(){
				news();
			});

         function checkAcceptCookies() {
				if(localStorage.getItem("acceptCookies") == 'true'){
					$('#cntCookies').hide();
				}
			}
			checkAcceptCookies();
      }
   })
}

mostrarHeaderFooter();
var urlPagina = window.location.pathname.split('?')[0];
if (urlPagina.substr(-1) == "/") urlPagina = urlPagina.substr(0, urlPagina.length - 1);
var dispositiu;
if (/Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent)) {
   dispositiu = "mobil";
   $('#boto-tancar').css('display', 'none');
   $('#top-menu').remove()
} else {
   dispositiu = "ordinador"
}

function mostrarUnPack() {
   /* Consultem la info d'un pack */
	var request = $.ajax({
		url: "https://www.prisma.cat/ajax/mostrar_pack.php",
		method: "GET",
		data: {
         url : urlPagina,
         dispositiu : dispositiu
      },
		dataType: "html"
	});

	/* Mostrem els apartats del menú lateral */
	request.done(function( infoPack ) {
      $("#contingut_curs").html(infoPack);
      adjustStyle();
      $("#torna").click(function(){
         tornaInici();
      });

      $('.formulari-llista-espera').on('focus', '.form-control', function(){
         $(this).prev().addClass('active');
      });
      $('.formulari-llista-espera').on('blur', '.form-control', function(){
         if ($(this).val()=='')
            $(this).prev().removeClass('active');
      });

      $('#modalLlistaBody').on('change', '#nom', function() {validacioNom("nom", "nom_erroni");});
      $('#modalLlistaBody').on('blur', '#nom', function() {validacioNom("nom", "nom_erroni");});
      $('#modalLlistaBody').on('focus', '#nom', function() {eliminarError("nom_erroni");});

      $('#modalLlistaBody').on('change', '#cog', function() {validacioCognoms("cog", "cog_erroni");});
      $('#modalLlistaBody').on('blur', '#cog', function() {validacioCognoms("cog", "cog_erroni");});
      $('#modalLlistaBody').on('focus', '#cog', function() {eliminarError("cog_erroni");});

      $('#modalLlistaBody').on('change', '#email', function() {validacioEmail("email", "correu_erroni");});
      $('#modalLlistaBody').on('blur', '#email', function() {validacioEmail("email", "correu_erroni");});
      $('#modalLlistaBody').on('focus', '#email', function() {eliminarError("correu_erroni");});

      $('#modalLlistaBody').on('change', '#telf', function() {validacioTelefon("telf", "telf_erroni");});
      $('#modalLlistaBody').on('blur', '#telf', function() {validacioTelefon("telf", "telf_erroni");});
      $('#modalLlistaBody').on('focus', '#telf', function() {eliminarError("telf_erroni");});

      $('#modalLlista').on('click', '#form_enviar_dades', function() {
          validacioFormulariLlista()
      });

      $('#modalBodyNoRec').on('change', '#nom-no-rec', function() {validacioNom("nom-no-rec", "nom_no_rec_erroni");});
      $('#modalBodyNoRec').on('blur', '#nom-no-rec', function() {validacioNom("nom-no-rec", "nom_no_rec_erroni");});
      $('#modalBodyNoRec').on('focus', '#nom-no-rec', function() {eliminarError("nom_no_rec_erroni");});

      $('#modalBodyNoRec').on('change', '#cog-no-rec', function() {validacioCognoms("cog-no-rec", "cog_no_rec_erroni");});
      $('#modalBodyNoRec').on('blur', '#cog-no-rec', function() {validacioCognoms("cog-no-rec", "cog_no_rec_erroni");});
      $('#modalBodyNoRec').on('focus', '#cog-no-rec', function() {eliminarError("cog_no_rec_erroni");});

      $('#modalBodyNoRec').on('change', '#email-no-rec', function() {validacioEmail("email-no-rec", "correu_no_rec_erroni");});
      $('#modalBodyNoRec').on('blur', '#email-no-rec', function() {validacioEmail("email-no-rec", "correu_no_rec_erroni");});
      $('#modalBodyNoRec').on('focus', '#email-no-rec', function() {eliminarError("correu_no_rec_erroni");});

      $('#modalBodyNoRec').on('change', '#telf-no-rec', function() {validacioTelefon("telf-no-rec", "telf_no_rec_erroni");});
      $('#modalBodyNoRec').on('blur', '#telf-no-rec', function() {validacioTelefon("telf-no-rec", "telf_no_rec_erroni");});
      $('#modalBodyNoRec').on('focus', '#telf-no-rec', function() {eliminarError("telf_no_rec_erroni");});

      $('#modalTextNoReconegut').on('click', '#form_enviar_dades', function() {
          validacioFormulariNoRec()
      });

      var video  = $(".video-responsive");
      video.on("click", function(){
         var obj = $(this);
         $(this).find('iframe')[0].src=$(this).find('iframe')[0].src.replace("autoplay=0", "autoplay=1");
         setTimeout(function(){
            obj.find('button').hide();
            obj.find('img').hide();
         },500);
      });

      //Pausar el video de presentacioq quan es canvii de pestanya i abans estava desplegada la pestanya de Descripció
      $('.info-descripcio-nav li a').on('click',function(){
        $('.sticky-sidebar').css("height", '780px');
        if($('#descripcio').css('display')=='block'){

          var src= $('#video-presentacio iframe')[0].src;
          $('#video-presentacio iframe')[0].src = src;
          $('#video-presentacio iframe')[0].src = src.replace("autoplay=1", "autoplay=0");
          $('#video-presentacio').find('img').show();
          $('#video-presentacio').find('button').show();
        }
      });
	});

	request.fail(function( jqXHR, textStatus, errorThrown ) {
		errorFunction( jqXHR, textStatus, errorThrown, "Hi ha hagut un error en el request: " );
	});
}

mostrarUnPack();

function sticky() {
   $(window).scroll(function(){ // scroll event
      scrollEventSticky();
   });
}

var screenWitdh = parseInt($(this).width());

function adjustStyle() {
   sticky();
   screenWidth = parseInt($(this).width());
   //Sticky
   if (screenWidth < 992) {
      $('.sticky-sidebar').attr("style", "height: " + $('.more-info').css('height') + "!important");
   }
   //footer
   if (screenWidth < 575) {
		$('.prisma-footer .panel').css('display', 'none');
		$('.accordion-footer').removeClass('active');
		$('.accordion-footer').click(function() {
			this.classList.toggle("active");
			var panel = this.nextElementSibling;
			if (panel.style.display === "block") {
				panel.style.display = "none";
				panel.style.maxHeight = null
			} else {
				panel.style.display = "block";
				panel.style.maxHeight = panel.scrollHeight + "px"
			}
		})
	}
	else {
		$('.accordion-footer').removeClass('active');
		$('.prisma-footer .panel').css('display', 'block')
	}
}

window.onscroll = function() {
   noPerdreHeader()
};

function noPerdreHeader() {
   if (document.body.scrollTop > 0 || document.documentElement.scrollTop > 0) {
      $('#top-menu').css('display', 'none');
      $('#nav-header').css('position', 'fixed')
   } else {
      if (!(/Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent)))
         $('#top-menu').css('display', 'block');
      $('#nav-header').css('position', 'inherit')
   }
}
